    zero_mat.m[0][0] = 0.0; zero_mat.m[0][1] = 0.0; zero_mat.m[0][2] = 0.0;
    zero_mat.m[1][0] = 0.0; zero_mat.m[1][1] = 0.0; zero_mat.m[1][2] = 0.0;
    zero_mat.m[2][0] = 0.0; zero_mat.m[2][1] = 0.0; zero_mat.m[2][2] = 0.0;
    *basis = zero_mat;
    *separation_sine = 0.0;
    return ADCS_E_DEGENERATE;
}

third = adcs_vec3_cross(&s_norm, &p_norm);

basis->m[0][0] = p_norm.x; basis->m[0][1] = p_norm.y; basis->m[0][2] = p_norm.z;
basis->m[1][0] = third.x;  basis->m[1][1] = third.y;  basis->m[1][2] = third.z;
basis->m[2][0] = s_norm.x; basis->m[2][1] = s_norm.y; basis->m[2][2] = s_norm.z;

return ADCS_OK;
